// Bindings are generated by `npm run types`. Dashboard-managed secrets are optional
// here because the deployed website must keep working before email is configured.
export type EnquiryEnv = Env & { RESEND_API_KEY?: string };

const ORIGINS = new Set([
  "https://paintandsipevents.com.au",
  "https://www.paintandsipevents.com.au",
]);
const EXPERIENCES = new Set([
  "Art Master Class", "Live Illustration", "Pre-event Illustration", "Not sure yet",
]);
const MAX_BODY_BYTES = 16_384;
const MAX_PROVIDER_BYTES = 4_096;
const TIMEOUT_MS = 10_000;

type Enquiry = {
  name: string;
  email: string;
  phone: string;
  experience: string;
  date: string;
  location: string;
  guests: string;
  eventType: string;
  message: string;
  website: string;
};

class RequestError extends Error {
  status: number;
  constructor(status: number, message: string) {
    super(message);
    this.status = status;
  }
}

function json(body: object, status = 200, extraHeaders: Record<string, string> = {}) {
  return Response.json(body, {
    status,
    headers: {
      "Cache-Control": "no-store",
      "X-Content-Type-Options": "nosniff",
      ...extraHeaders,
    },
  });
}

/** Read incrementally, refusing oversized streams even without Content-Length. */
async function boundedText(body: ReadableStream<Uint8Array> | null, max: number): Promise<string> {
  if (!body) throw new RequestError(400, "A JSON body is required.");
  const reader = body.getReader();
  let bytes = 0;
  const chunks: Uint8Array[] = [];
  let timer: ReturnType<typeof setTimeout> | undefined;
  const timeout = new Promise<never>((_, reject) => {
    timer = setTimeout(() => {
      void reader.cancel().catch(() => undefined);
      reject(new RequestError(408, "The request took too long. Please try again."));
    }, TIMEOUT_MS);
  });
  try {
    while (true) {
      const { done, value } = await Promise.race([reader.read(), timeout]);
      if (done) break;
      bytes += value.byteLength;
      if (bytes > max) {
        void reader.cancel().catch(() => undefined);
        throw new RequestError(413, "The request is too large.");
      }
      chunks.push(value);
    }
    const result = new Uint8Array(bytes);
    let offset = 0;
    for (const chunk of chunks) {
      result.set(chunk, offset);
      offset += chunk.byteLength;
    }
    return new TextDecoder("utf-8", { fatal: true, ignoreBOM: false }).decode(result);
  } finally {
    if (timer !== undefined) clearTimeout(timer);
    reader.releaseLock();
  }
}

function validate(value: unknown): Enquiry {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new RequestError(400, "Please provide valid enquiry details.");
  }
  const input = value as Record<string, unknown>;
  const limits = {
    name: 100, email: 254, phone: 40, experience: 50, date: 120,
    location: 200, guests: 5, eventType: 120, message: 4000, website: 200,
  };
  if (Object.keys(input).some((key) => !Object.hasOwn(limits, key))) {
    throw new RequestError(400, "Unexpected enquiry fields.");
  }
  const cleaned: Record<string, string> = {};
  for (const [key, max] of Object.entries(limits)) {
    const raw = input[key] ?? ((key === "message" || key === "website") ? "" : undefined);
    if (typeof raw !== "string" || raw.length > max || /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/.test(raw)) {
      throw new RequestError(400, `Please check the ${key} field.`);
    }
    const text = raw.trim();
    if (key !== "message" && key !== "website" && (!text || /[\r\n]/.test(raw))) {
      throw new RequestError(400, `Please check the ${key} field.`);
    }
    cleaned[key] = text;
  }
  if (cleaned.website) throw new RequestError(400, "Unable to submit this enquiry.");
  if (!/^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9](?:[A-Za-z0-9.-]*[A-Za-z0-9])?\.[A-Za-z]{2,63}$/.test(cleaned.email) || cleaned.email.includes("..")) {
    throw new RequestError(400, "Please enter a valid email address.");
  }
  if (!/^[+()\d .-]{5,40}$/.test(cleaned.phone) || cleaned.phone.replace(/\D/g, "").length < 5 || !EXPERIENCES.has(cleaned.experience)) {
    throw new RequestError(400, "Please check your phone number and experience.");
  }
  if (!/^\d{1,5}$/.test(cleaned.guests) || Number(cleaned.guests) < 1 || Number(cleaned.guests) > 10000) {
    throw new RequestError(400, "Please enter a guest count between 1 and 10,000.");
  }
  return cleaned as Enquiry;
}

function checkOrigin(request: Request) {
  const url = new URL(request.url);
  const origin = request.headers.get("Origin");
  if (!origin || !ORIGINS.has(origin) || origin !== url.origin || request.headers.get("Sec-Fetch-Site") === "cross-site") {
    throw new RequestError(403, "Please submit this form from our website.");
  }
}

function emailText(enquiry: Enquiry) {
  return [
    "New Paint & Sip Events website enquiry", "",
    `Name: ${enquiry.name}`, `Email: ${enquiry.email}`, `Phone: ${enquiry.phone}`,
    `Experience: ${enquiry.experience}`, `Preferred date and time: ${enquiry.date}`,
    `Location: ${enquiry.location}`, `Guest count: ${enquiry.guests}`,
    `Event type: ${enquiry.eventType}`, "", "Message:", enquiry.message || "No additional message.",
  ].join("\n");
}

async function sendEnquiry(enquiry: Enquiry, apiKey: string, fetcher: typeof fetch, requestId: string) {
  let response: Response;
  try {
    response = await fetcher("https://api.resend.com/emails", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json",
        "Idempotency-Key": `enquiry-${requestId}`,
      },
      body: JSON.stringify({
        from: "Paint & Sip Events <enquiries@paintandsipevents.com.au>",
        to: ["hello@anthonypietersartist.com"],
        reply_to: enquiry.email,
        subject: `Paint & Sip Events enquiry — ${enquiry.experience}`,
        text: emailText(enquiry),
      }),
      signal: AbortSignal.timeout(TIMEOUT_MS),
    });
  } catch {
    console.error(JSON.stringify({ event: "enquiry_provider_unavailable", requestId }));
    throw new RequestError(502, "Your enquiry could not be sent. Please try again or contact Anthony directly.");
  }
  if (!response.ok) {
    void response.body?.cancel().catch(() => undefined);
    console.error(JSON.stringify({ event: "enquiry_provider_rejected", requestId, status: response.status }));
    throw new RequestError(502, "Your enquiry could not be sent. Please try again or contact Anthony directly.");
  }
  let accepted = false;
  try {
    const result: unknown = JSON.parse(await boundedText(response.body, MAX_PROVIDER_BYTES));
    accepted = !!result && typeof result === "object" && "id" in result && typeof result.id === "string" && result.id.length > 0;
  } catch {
    // Never report a send as successful without an explicit provider receipt.
  }
  if (!accepted) {
    console.error(JSON.stringify({ event: "enquiry_provider_invalid_receipt", requestId }));
    throw new RequestError(502, "Email confirmation was unavailable. Please contact Anthony directly before retrying.");
  }
  console.info(JSON.stringify({ event: "enquiry_accepted", requestId }));
}

/** Exported for deterministic tests; no test-only routes or environment switches. */
export async function handleRequest(request: Request, env: EnquiryEnv, fetcher: typeof fetch = fetch): Promise<Response> {
  const path = new URL(request.url).pathname;
  if (path === "/api/enquiry/status") {
    if (request.method !== "GET") return json({ error: "Method not allowed." }, 405, { Allow: "GET" });
    return json({ configured: Boolean(env.RESEND_API_KEY?.trim()) });
  }
  if (path !== "/api/enquiry") {
    if (path.startsWith("/api/")) return json({ error: "Not found." }, 404);
    return env.ASSETS.fetch(request);
  }
  if (request.method !== "POST") return json({ error: "Method not allowed." }, 405, { Allow: "POST" });
  const requestId = crypto.randomUUID();
  try {
    checkOrigin(request);
    if (request.headers.get("Content-Type")?.split(";")[0].trim().toLowerCase() !== "application/json") {
      throw new RequestError(415, "Please send JSON enquiry details.");
    }
    const length = request.headers.get("Content-Length");
    if (length && (!/^\d+$/.test(length) || Number(length) > MAX_BODY_BYTES)) {
      throw new RequestError(413, "The request is too large.");
    }
    let input: unknown;
    try {
      input = JSON.parse(await boundedText(request.body, MAX_BODY_BYTES));
    } catch (error) {
      if (error instanceof RequestError) throw error;
      throw new RequestError(400, "Please provide valid JSON enquiry details.");
    }
    const enquiry = validate(input);
    const secret = env.RESEND_API_KEY?.trim();
    if (!secret) throw new RequestError(503, "Direct enquiries are being configured. Please email or call Anthony for now.");
    const ip = request.headers.get("CF-Connecting-IP") || "unknown";
    const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(ip));
    const key = `enquiry:${Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, "0")).join("")}`;
    const { success } = await env.ENQUIRY_RATE_LIMITER.limit({ key });
    if (!success) return json({ error: "Too many enquiries. Please wait a minute before trying again." }, 429, { "Retry-After": "60" });
    await sendEnquiry(enquiry, secret, fetcher, requestId);
    return json({ success: true, message: "Your enquiry has been sent to Anthony." });
  } catch (error) {
    if (error instanceof RequestError) return json({ error: error.message }, error.status);
    console.error(JSON.stringify({ event: "enquiry_unexpected_error", requestId }));
    return json({ error: "Your enquiry could not be sent. Please contact Anthony directly." }, 500);
  }
}

export default {
  fetch(request, env) {
    return handleRequest(request, env);
  },
} satisfies ExportedHandler<EnquiryEnv>;
